-- By definition of intersection and union, we have:
-- s ∩ (s ∪ t) = {x | x ∈ s ∧ x ∈ (s ∪ t)}
-- Since x ∈ (s ∪ t) iff x ∈ s ∨ x ∈ t, we get:
-- {x | x ∈ s ∧ (x ∈ s ∨ x ∈ t)}
-- By logical equivalence, this is equivalent to:
-- {x | x ∈ s ∧ x ∈ s} ∪ {x | x ∈ s ∧ x ∈ t}
-- Which simplifies to:
-- {x | x ∈ s} ∪ {x | x ∈ s ∧ x ∈ t}
-- The first part is exactly s, and the second part is a subset of s
-- because if x ∈ s ∧ x ∈ t, then x ∈ s.
-- Therefore, s ∩ (s ∪ t) = s

-- Using the definition of set equality
exact set_eq_of_subset_and_subset
  (by { -- Show s ⊆ s ∩ (s ∪ t)
      intro x
      have : x ∈ s ∪ t := by { cases : x ∈ s; left; right }
      exact ⟨by { apply set_membership.mpr; exact x ∈ s }, by { apply set_membership.mpr; exact this }⟩
    })
  (by { -- Show s ∩ (s ∪ t) ⊆ s
      intro x
      have : x ∈ s ∩ (s ∪ t) := rfl
      have : x ∈ s ∧ x ∈ (s ∪ t) := by { apply set_membership.mpr; exact this }
      have : x ∈ s ∨ x ∈ t := by { apply set_membership.mpr; exact (by { apply and_intro; left; exact this.1 }) }
      have : x ∈ s := by { cases : x ∈ s ∨ x ∈ t; left; exact this.1 }
      exact ⟨by { apply set_membership.mpr; exact this.2 }, this⟩
    })

